-- Read-only audit SELECTs; captured via Supabase /database/query/read-only.
-- For psql, use a read-only login plus PGOPTIONS=-cdefault_transaction_read_only=on.
-- No application stored routine is invoked by these catalog/probe queries.
select 'meta' category,jsonb_build_object('captured_at',now(),'role',current_user,'read_only',current_setting('transaction_read_only')) data
union all select 'nonpublic_routines',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'security_definer',p.prosecdef,'definition_md5',md5(pg_get_functiondef(p.oid))) order by n.nspname,p.proname),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not like 'pg_%' and n.nspname not in ('public','information_schema') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')
union all select 'nonpublic_policies',coalesce(jsonb_agg(to_jsonb(p) order by p.schemaname,p.tablename,p.policyname),'[]') from pg_policies p where schemaname not in ('public')
union all select 'nonpublic_triggers',coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname not like 'pg_%' and n.nspname not in ('public','information_schema') and not t.tgisinternal
union all select 'event_invariants',jsonb_build_object('event_rooms_showcase_on',(select count(*) from public.communities where type='event' and showcase_enabled=true),'event_rooms_not_chat_only',(select count(*) from public.communities where type='event' and enabled_tabs<>array['chat']::text[]),'report_orphans',(select count(*) from public.interaction_reports r where reporter_id is not null and not exists(select 1 from public.users u where u.id=r.reporter_id)), 'client_readable_column_grants',(select count(*) from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated') and privilege_type='SELECT'))
union all select 'settings',jsonb_build_object('creation_limits',(select jsonb_agg(to_jsonb(c) order by kind) from public.creation_limits c),'verification_grace_days',(select grace_days from public.verification_settings where id=true));
